dirs=[(2,0),(-2,0),(0,2),(0,-2)]
@lru_cache(None)
def solve(state):
    if len(state)==1:return []
    for x,y in state:
      for dx,dy in dirs:
        mid=(x+dx//2,y+dy//2); dst=(x+dx,y+dy)
        if mid in state and dst in valid and dst not in state:
          ns=frozenset((state-{(x,y),mid})|{dst})
          r=solve(ns)
          if r is not None:return [((x,y),dst)]+r
    return None
